{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "In healthy volunteers, nocloprost, a prostaglandin analogue with a cyclopentane ring and carboxylic acid side chain, had an absolute oral bioavailability of about 2% that was independent of dose (100–400 µg), indicating very low systemic availability for this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Testosterone undecanoate, a lipophilic long-chain fatty acid ester, had a mean absolute oral bioavailability of 6.8 ± 3.3% in humans, showing that highly lipophilic carboxylic acid-derived structures can have F well below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Alpha-lipoic acid, a small carboxylic acid, achieved a mean oral bioavailability of 29.1% in healthy volunteers, demonstrating that carboxylic acid ionization alone does not preclude F ≥ 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Iloprost, a prostacyclin analogue with a carboxylic acid side chain, showed 56–63% absolute oral bioavailability in two TAO patients at a low 50 µg extended-release dose, but this is a special formulation and disease context with limited transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Myristic acid, a simple long-chain fatty acid, had 28% oral bioavailability in humans, suggesting some fatty-acid-like absorption can occur despite ionization.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%). The most structurally relevant experimental evidence, nocloprost, shows ~2% absolute F in humans; other lipophilic long-chain/steroid analogues also show low F. High-F examples are smaller or special-case molecules with lower transferability. The physicochemical prior (fully ionized carboxylic acid, high flexibility) is consistent with low F.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself in the provided evidence.",
    "Closest analogue nocloprost has low Morgan similarity to the query.",
    "Iloprost high-F data are from a small, disease-specific, low-dose extended-release study.",
    "No data on active transport, gut-wall metabolism, or formulation effects for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

